use std :: collections :: BTreeMap ; use std :: ops :: Deref ; use derive_more :: { Deref , Display , From } ; use derive_setters :: Setters ; use merge :: Merge ; use serde :: { Deserialize , Serialize } ; use strum_macros :: { Display as StrumDisplay , EnumIter , EnumString } ; use serde :: de ; use std :: hash :: { Hash , Hasher } ; use super :: * ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_ne ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use fake :: { Fake , Faker } ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; impl McpServerConfig { # [doc = " Create a new stdio-based MCP server"] pub fn new_stdio (command : impl Into < String > , args : Vec < String > , env : Option < BTreeMap < String , String > > ,) -> Self { Self :: Stdio (McpStdioServer { command : command . into () , args , env : env . unwrap_or_default () , timeout : None , disable : false , }) } # [doc = " Create a new HTTP-based MCP server (auto-detects transport type)"] pub fn new_http (url : impl Into < String >) -> Self { Self :: Http (McpHttpServer { url : url . into () , headers : BTreeMap :: new () , timeout : None , disable : false , oauth : McpOAuthSetting :: AutoDetect , }) } pub fn is_disabled (& self) -> bool { match self { McpServerConfig :: Stdio (v) => v . disable , McpServerConfig :: Http (v) => v . disable , } } # [doc = " Returns the type of MCP server as a string (\"STDIO\" or \"HTTP\")"] pub fn server_type (& self) -> & 'static str { match self { McpServerConfig :: Stdio (_) => "STDIO" , McpServerConfig :: Http (_) => "HTTP" , } } }